31	// ---------- com/study/app/command/OrderAggregate.java ----------
32	package com.study.app.command;
33	
34	import org.axonframework.commandhandling.CommandHandler;
35	import org.axonframework.eventsourcing.EventSourcingHandler;
36	import org.axonframework.modelling.command.AggregateIdentifier;
37	import org.axonframework.spring.stereotype.Aggregate;
38	
39	import static org.axonframework.modelling.command.AggregateLifecycle.apply;
40	
41	@Aggregate
42	public class OrderAggregate {
43	
44	    enum Status { PENDING, CONFIRMED, REJECTED }
45	
46	    @AggregateIdentifier private String orderId;
47	    private Status status;
48	
49	    protected OrderAggregate() {}                    // required no-arg ctor for event sourcing
50	
51	    @CommandHandler                                  // CONSTRUCTOR handler -> creates aggregate
52	    public OrderAggregate(CreateOrderCommand cmd) {
53	        if (cmd.quantity() < 1) throw new IllegalArgumentException("quantity must be >= 1");
54	        apply(new OrderCreatedEvent(cmd.orderId(), cmd.customerId(), cmd.productId(), cmd.quantity()));
55	    }
56	
57	    @CommandHandler
58	    public void handle(ConfirmOrderCommand cmd) {
59	        if (status != Status.PENDING) return;        // idempotent: no event if already decided
60	        apply(new OrderConfirmedEvent(orderId, cmd.total()));
61	    }
62	
63	    @CommandHandler
64	    public void handle(RejectOrderCommand cmd) {
65	        if (status != Status.PENDING) return;
66	        apply(new OrderRejectedEvent(orderId, cmd.reason()));
67	    }
68	
69	    @EventSourcingHandler                            // ONLY place state changes
70	    public void on(OrderCreatedEvent e) { this.orderId = e.orderId(); this.status = Status.PENDING; }
71	
72	    @EventSourcingHandler
73	    public void on(OrderConfirmedEvent e) { this.status = Status.CONFIRMED; }
74	
75	    @EventSourcingHandler
76	    public void on(OrderRejectedEvent e) { this.status = Status.REJECTED; }
77	}
