81	// ---------- com/study/app/command/OrderSaga.java ----------
82	// Drives reserve -> charge -> confirm / reject+release (compensation).
83	// (ReserveStockCommand/ChargeCommand/ReleaseStockCommand + their events live in
84	//  the corresponding product/customer aggregates, elided here.)
85	package com.study.app.command;
86	
87	import com.study.app.command.*;
88	import org.axonframework.commandhandling.gateway.CommandGateway;
89	import org.axonframework.modelling.saga.EndSaga;
90	import org.axonframework.modelling.saga.SagaEventHandler;
91	import org.axonframework.modelling.saga.SagaLifecycle;
92	import org.axonframework.modelling.saga.StartSaga;
93	import org.axonframework.spring.stereotype.Saga;
94	import org.springframework.beans.factory.annotation.Autowired;
95	
96	@Saga
97	public class OrderSaga {
98	
99	    @Autowired private transient CommandGateway gateway;   // transient: not serialized into saga state
100	    private transient int total;                           // recomputed; demo only
101	
102	    @StartSaga
103	    @SagaEventHandler(associationProperty = "orderId")
104	    public void on(OrderCreatedEvent e) {
105	        SagaLifecycle.associateWith("productId", e.productId().toString());
106	        gateway.send(new ReserveStockCommand(e.productId(), e.orderId(), e.quantity()));
107	    }
108	
109	    @SagaEventHandler(associationProperty = "orderId")
110	    public void on(StockReservedEvent e) {
111	        this.total = e.total();
112	        gateway.send(new ChargeCommand(e.customerId(), e.orderId(), e.total()));
113	    }
114	
115	    @SagaEventHandler(associationProperty = "orderId")
116	    public void on(ChargedEvent e) {
117	        gateway.send(new ConfirmOrderCommand(e.orderId(), total));
118	    }
119	
120	    @SagaEventHandler(associationProperty = "orderId")
121	    public void on(ChargeFailedEvent e) {
122	        gateway.send(new ReleaseStockCommand(e.productId(), e.quantity()));   // COMPENSATION
123	        gateway.send(new RejectOrderCommand(e.orderId(), "INSUFFICIENT_FUNDS"));
124	    }
125	
126	    @EndSaga @SagaEventHandler(associationProperty = "orderId")
127	    public void on(OrderConfirmedEvent e) { /* terminal */ }
128	
129	    @EndSaga @SagaEventHandler(associationProperty = "orderId")
130	    public void on(OrderRejectedEvent e) { /* terminal */ }
131	}
132	```
