267	// ---------- com/study/app/web/OrderController.java ----------
268	package com.study.app.web;
269	
270	import com.study.app.command.CreateOrderCommand;
271	import com.study.app.query.*;
272	import org.axonframework.commandhandling.gateway.CommandGateway;
273	import org.axonframework.messaging.responsetypes.ResponseTypes;
274	import org.axonframework.queryhandling.QueryGateway;
275	import org.springframework.http.HttpStatus;
276	import org.springframework.web.bind.annotation.*;
277	import org.springframework.web.server.ResponseStatusException;
278	
279	import java.util.Map;
280	import java.util.UUID;
281	import java.util.concurrent.ExecutionException;
282	
283	@RestController
284	@RequestMapping("/orders")
285	public class OrderController {
286	
287	    private final CommandGateway commandGateway;
288	    private final QueryGateway queryGateway;
289	
290	    public OrderController(CommandGateway commandGateway, QueryGateway queryGateway) {
291	        this.commandGateway = commandGateway; this.queryGateway = queryGateway;
292	    }
293	
294	    public record CreateOrder(UUID orderId, UUID customerId, UUID productId, int quantity) {}
295	
296	    @PostMapping
297	    @ResponseStatus(HttpStatus.ACCEPTED)   // 202; processing is async via saga + projection
298	    public Map<String, Object> create(@RequestBody CreateOrder b) {
299	        // idempotency: re-sending the same orderId hits the existing aggregate's
300	        // constructor-vs-existing routing; a duplicate create is rejected and can
301	        // be treated as already-accepted by inspecting the read model.
302	        commandGateway.send(new CreateOrderCommand(b.orderId().toString(),
303	                b.customerId(), b.productId(), b.quantity()));
304	        return Map.of("orderId", b.orderId(), "status", "PENDING");
305	    }
306	
307	    @GetMapping("/{id}")
308	    public OrderView get(@PathVariable String id) throws ExecutionException, InterruptedException {
309	        OrderView v = queryGateway.query(new FindOrder(id), ResponseTypes.instanceOf(OrderView.class)).get();
310	        if (v == null) throw new ResponseStatusException(HttpStatus.NOT_FOUND);  // may be in-flight; client polls
311	        return v;
312	    }
313	}
314	```
315	
316	### Why this is correct under concurrency
317	- **Single source of truth per invariant:** stock lives in a product aggregate,
318	  balance in a customer aggregate; their command streams serialize per aggregate
319	  (sequence-number optimistic concurrency), so no oversell / overdraw. Losing
320	  commands get `ConcurrencyException` and are retried.
321	- **Idempotency:** the order id is the aggregate id; a duplicate create command
322	  cannot create a second aggregate at sequence 0, and the confirm/reject method
323	  handlers are no-ops once status leaves PENDING.
324	- **Saga compensation:** charge failure triggers `ReleaseStockCommand` +
325	  `RejectOrderCommand`.
326	- **Exactly-once notification:** the projection writes the read-model row and the
327	  notification in the processor's transaction (token advances with it); the
328	  `UNIQUE(orderId)` makes a replayed event idempotent (at-least-once → effectively
329	  once).
330	- **Eventual consistency:** views update when the tracking processor polls;
331	  `GET` may briefly 404 until the projection catches up — clients poll within the
332	  convergence window.
333

